<?php

namespace Database\Seeders;

use App\Models\BlogCategory;
use App\Models\BlogPost;
use Carbon\Carbon;
use Illuminate\Database\Seeder;

class BlogPostSeeder extends Seeder
{
    public function run(): void
    {
        if (BlogPost::count() > 0) {
            return;
        }

        $categoryIds = BlogCategory::pluck('id', 'slug')->all();

        // First post goes live on the next business day at 10:00
        $startDate = Carbon::now()->addWeekday()->setTime(10, 0, 0);

        $posts = array_merge(
            $this->weddingPosts($categoryIds),
            $this->baptismPosts($categoryIds),
            $this->promPosts($categoryIds),
            $this->behindPosts($categoryIds),
            $this->stylePosts($categoryIds),
        );

        foreach ($posts as $index => $data) {
            $publishedAt = $startDate->copy()->addWeekdays($index * 4);

            BlogPost::create(array_merge($data, [
                'is_published' => true,
                'published_at' => $publishedAt,
            ]));
        }
    }

    private function weddingPosts(array $cats): array
    {
        $catId = $cats['wedding-tips'] ?? null;
        $cover = 'css/img/Edited_IMG_9630.jpg';

        return [
            [
                'title' => 'Как да изберете сватбен фотограф във Варна - 7 ключови въпроса',
                'slug' => 'kak-da-izberete-svatben-fotograf-varna',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Изборът на сватбен фотограф е едно от най-важните решения при планиране на сватбата. Ето 7-те въпроса, които задължително трябва да зададете, преди да подпишете договор.',
                'meta_description' => '7 въпроса, които трябва да зададете на сватбения си фотограф във Варна преди да го наемете. Практичен гид от Take Two Studio.',
                'body' => '<p>Изборът на сватбен фотограф не е като наемане на коя да е услуга. Това е човекът, който ще документира един от най-важните дни в живота ви - и резултатът ще остане завинаги. В този гид споделяме 7-те въпроса, които задължително трябва да зададете на всеки фотограф, преди да вземете решение.</p><h2>1. Колко пълни сватби сте снимали?</h2><p>Има разлика между 10 сватби и 100. С опита идват увереност, предвиждане на ключовите моменти и способност за реакция при непредвидени ситуации. Опитните фотографи знаят кога ще се появи сълзата, кога булката ще погледне младоженеца и кога светлината ще стане златна.</p><h2>2. Какъв е вашият стил на фотография?</h2><p>Репортажен, класически, fine art, dark &amp; moody, светъл и въздушен - всеки фотограф има собствен почерк. Поискайте да видите 2-3 пълни сватби от начало до край, а не само best-of колекция. Това ще ви даде реална представа какъв ще е албумът ви.</p><h2>3. Какво пише в договора?</h2><p>Професионалният фотограф винаги работи с договор. В него трябва ясно да са описани: часове покритие, брой фотографи, време за предаване на материалите, какво се случва при форсмажор, правата върху снимките и условията за отказ.</p><h2>4. Кога ще получим готовите снимки?</h2><p>Стандартният срок в индустрията е между 30 и 60 работни дни. Ако някой обещава за седмица - внимавайте. Качествената обработка на 600-800 снимки отнема време. Ако някой иска 6 месеца - също внимавайте.</p><h2>5. Какъв е резервният ви план?</h2><p>Какво се случва, ако фотографът се разболее в деня на сватбата? Има ли двойна екипировка? Работи ли със замяна? Това са въпроси, които никой не обича да задава, но които правят разликата между спокойствие и катастрофа.</p><h2>6. Какво точно включва цената?</h2><p>Един пакет от 2000 лева може да включва 8 часа, 300 снимки и нищо друго. Друг пакет от 2500 лева може да включва 10 часа, 700 снимки, албум, видео тийзър и втори фотограф. Винаги сравнявайте what you get, не само цената.</p><h2>7. Имаме ли химия?</h2><p>Най-подценяваният въпрос. Ще прекарате с този човек 8-12 часа в най-емоционалния ден от живота си. Ако още на първата среща ви е неудобно - това няма да се оправи в деня на сватбата. Изберете човек, с когото се чувствате комфортно.</p><blockquote>Съвет от нас: не бързайте. Срещнете се лично с поне 3 фотографа, преди да вземете решение. Снимките са това, което ще останe, когато всичко друго отшуми.</blockquote><p>Ако искате да разберете как работим ние в Take Two Studio, свържете се с нас за безплатна консултация. Ще отговорим честно на всички тези 7 въпроса - и на всеки друг, който имате.</p>',
            ],
            [
                'title' => 'Сватбен Getting Ready - защо първият час е най-важният за албума',
                'slug' => 'svatben-getting-ready-purvi-chas',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Много двойки подценяват сутрешната подготовка и искат фотографът да пристигне малко преди церемонията. Това е грешка, която струва най-емоционалните кадри в деня.',
                'meta_description' => 'Защо сватбеният Getting Ready е най-важният момент за вашия албум и как да го планирате правилно.',
                'body' => '<p>Попитайте коя да е булка, кой е най-любимият й кадър от сватбеното видео. В 80% от случаите отговорът е не първият танц, не церемонията и не тортата - а моментът, в който майка й помага с роклята, а приятелките й се смеят в дъното на кадъра. Това е магията на Getting Ready.</p><h2>Защо сутринта има различна светлина</h2><p>Ако подготовката е сутрин между 9 и 12 часа, в стаята влиза мека, разсеяна естествена светлина. Тя прави кожата да изглежда свежа, очите - живи, а детайлите по роклята - деликатни. Това е светлината, която професионалните фотографи обожават и която е невъзможно да се пресъздаде по-късно през деня.</p><h2>Емоциите са истински, защото денят още не е започнал</h2><p>В 10 сутринта булката още не е разгласена. Приятелките още не са пили шампанско. Мама още не е видяла момичето си в роклята. Това означава, че всяка емоция, която уловим, е първа, истинска и неповторима. Няма повторения.</p><h3>Кадрите, които не бива да пропускате</h3><ul><li>Роклята, закачена до прозореца</li><li>Обувките, пръстенът и бижутата в композиция</li><li>Мама, която слага воала</li><li>Реакцията на татко, когато види дъщеря си готова</li><li>Bouquet toss на приятелките преди излизане</li><li>Последният поглед в огледалото</li></ul><h2>Колко време всъщност трябва на фотографа</h2><p>Минимум 90 минути на една локация. Ако младоженецът е на друго място, това означава или втори фотограф, или 2 часа за нашата локация плюс пътуване. Всичко под това и започваме да прескачаме кадри.</p><h2>Често срещани грешки</h2><p>Грешка №1: оставяте разхвърляни кутии, чаши и дрехи навсякъде. Съвет: изберете един ъгъл от стаята като "чист", където ще се случват кадрите.</p><p>Грешка №2: прекалено много хора в стаята. 15 души около булката означава, че няма как да я снимаме без 14 други глави в кадъра. Ограничете до най-близките.</p><p>Грешка №3: готовността свършва 10 минути преди тръгване. Ние имаме нужда от 20-30 минути с вас след като сте готови, за детайли и портрети. Планирайте това в таймлайна.</p><blockquote>Ако можем да дадем само един съвет за целия сватбен ден, той е: не съкращавайте Getting Ready. Дайте му време, дайте му пространство, и ни позволете да го разкажем.</blockquote>',
            ],
            [
                'title' => 'Локации за сватбена фотосесия в и около Варна',
                'slug' => 'lokacii-svatbena-fotosesiya-varna',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Варна и регионът предлагат удивително разнообразие от места за сватбена фотосесия. От морски скали до стари каменни улички - ето нашите любими локации и кога да ги посетите.',
                'meta_description' => 'Най-добрите локации за сватбена фотосесия във Варна и региона - морски, градски и природни. Съвети от Take Two Studio.',
                'body' => '<p>Едно от предимствата да се жените във Варна е, че нямате нужда да пътувате далеч за впечатляваща фотосесия. Градът и околностите му предлагат морски пейзажи, стара архитектура, гори, скали и усамотени плажове - всичко в радиус от 40 минути. Ето нашите любими локации.</p><h2>Морска градина и крайбрежната алея</h2><p>Класика, която работи винаги. В ранния следобед светлината е мека между дърветата, а алеите са красиви. Най-доброто време: 1-2 часа преди залез. Избягвайте почивните дни по пладне, когато е пренаселено.</p><h2>Аладжа манастир</h2><p>Скални отвеси, пещери и уникална атмосфера. Идеално за двойки, които искат драматични, кинематографични кадри. Минус: затваря в 18:00, така че трябва да планирате предварително.</p><h2>Евксиноград</h2><p>Старата резиденция с прилежащия парк и морския бряг. Необходимо е предварително разрешение, но резултатът е впечатляващ - съчетание на архитектура, вода и зеленина.</p><h2>Шабленски фар и плажовете на север</h2><p>Ако сте готови за 40 минути път до Шабла, ще получите локация без други хора, с безкраен хоризонт и най-красиви залези на Черно море. За двойки, които искат "само ние двамата и морето".</p><h3>Локации в града</h3><ul><li>Стара Варна - каменни улички около Катедралата, перфектно за черно-бели кадри</li><li>Римските терми - древна архитектура като фон</li><li>Фестивалният и конгресен център - модерни линии и контрасти</li><li>Пристанището при залез - лодки, отражения, златна светлина</li></ul><h2>Локации извън града</h2><p><strong>Побити камъни</strong> - surreal каменни колони сред равнина, за уникални и необичайни кадри. Най-добре рано сутринта.</p><p><strong>Нос Калиакра</strong> - червени скали над морето, около 1 час от Варна. Драматично и величествено.</p><p><strong>Златни пясъци гора</strong> - зелени гори и сенчести пътеки, съвсем близо до града. Отлично за летни сватби.</p><h2>Кога да снимаме - златен час</h2><p>Независимо от локацията, най-добрата светлина е в последния час преди залез слънце - т.нар. golden hour. Планирайте фотосесията така, че тя да попадне в този прозорец. Ние винаги правим индивидуален таймлайн според датата на сватбата и точния час на залеза за този ден.</p><blockquote>Няма една "перфектна" локация. Има перфектна локация за вашата история. Кажете ни какво обичате, и ние ще ви предложим места, за които дори не сте мислили.</blockquote>',
            ],
            [
                'title' => 'First Look - какво е и защо все повече двойки го избират',
                'slug' => 'first-look-svatba',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'First Look е моментът, в който младоженецът вижда булката за пръв път преди церемонията - насаме, без публика. Ето защо тази традиция печели все повече фенове.',
                'meta_description' => 'Какво е First Look на сватба, предимства и недостатъци, и защо все повече двойки го избират за най-емоционалния момент от деня.',
                'body' => '<p>Преди 20 години никой у нас не беше чувал за First Look. Днес около 30% от двойките, с които работим, го избират. Това е моментът, в който младоженецът вижда булката за пръв път - не в църквата пред 150 души, а насаме, някъде спокойно, час-два преди церемонията.</p><h2>Защо някои двойки избират First Look</h2><p>Основната причина е емоционална. Много младоженци споделят, че не се чувстват комфортно да "изпитат" най-силната си емоция пред цяла зала. First Look дава на двойката собствен момент - 5-10 минути, в които целият свят спира.</p><p>Има и практична страна: след First Look можете да направите семейните портрети и portrait session преди церемонията, вместо след нея. Това освобождава часове за приятелите и семейството ви в рецепцията.</p><h2>Как го организираме</h2><p>Намираме тиха локация - парк, двор, вътрешен двор на хотел. Младоженецът стои с гръб. Булката се приближава. Ние снимаме от две страни - едната камера хваща неговия поглед, другата нейния. Когато я докосне, превключваме на видео за звука.</p><blockquote>Често казваме на младоженците: "Обърни се, когато чуеш стъпките й." Десет секунди по-късно виждаме реакция, която не може да се постави в сценарий.</blockquote><h2>Плюсове на First Look</h2><ul><li>Частен момент само за двойката</li><li>По-малко стрес преди церемонията</li><li>Може да плачете колкото искате</li><li>Портрети със сутрешна светлина и свежи прически</li><li>Повече време с гостите след церемонията</li></ul><h2>Минуси на First Look</h2><ul><li>Нарушава традицията "не виждаш булката преди олтара"</li><li>Някои смятат, че отнема магията на влизането в църквата</li><li>Изисква по-ранна подготовка сутринта</li><li>Не всички места позволяват удобен First Look setup</li></ul><h2>А реакцията в църквата?</h2><p>Хубавата новина: дори и да сте направили First Look, моментът пред олтара остава специален. Много младоженци споделят, че са дори по-трогнати, защото първото напрежение вече е минало и сега могат да се наслаждават изцяло на церемонията.</p><h2>Нашият съвет</h2><p>First Look не е за всички. Ако сте традиционни и мисълта "да я видя за пръв път на олтара" е свещена за вас - не го правете насила. Но ако сте двойка, която иска частни моменти и спокойствие, помислете сериозно. Не съжаляваме за нито един First Look, който сме снимали.</p>',
            ],
            [
                'title' => 'Таймлайн за перфектен снимачен ден на сватба',
                'slug' => 'taymlayn-snimachen-den-svatba',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Един добър сватбен таймлайн не е просто списък на събития - той е инструмент, който позволява на фотографа да хване емоцията, без да ви притеснява с "трябва да правим портрети".',
                'meta_description' => 'Как изглежда перфектният таймлайн за сватбен ден от фотографска гледна точка - по часове, със съвети за буфер и светлина.',
                'body' => '<p>Най-честата причина сватбени снимки да се провалят не е техниката или осветлението - а лошият таймлайн. Булката е под стрес, защото всичко закъснява. Семейните портрети се правят на тъмно. Няма време за двойката да изляза за златния час. Ето как изглежда един добре планиран ден.</p><h2>10:00 - Getting Ready на булката</h2><p>Фотографът пристига. Първите 30 минути - детайли: роклята, обувките, бижутата, поканата, букета. Паралелно приятелките и мама са с булката в съседна стая.</p><h2>11:00 - Подготовка с приятелките</h2><p>Нанасяне на финалния грим. Обличане. Реакцията на мама, когато я види готова. Това е най-емоционалният отрязък от деня.</p><h2>11:45 - Готовност за тръгване</h2><p>15-20 минути портрети на булката сама, с приятелките, с родителите. Ако сте планирали First Look - той се случва сега.</p><h2>12:30 - Ритуал "изкарване на булката"</h2><p>Ако е по българска традиция - това отнема 20-30 минути с традициите, смехове и сълзи.</p><h2>13:30 - Пристигане в църквата/залата</h2><p>15 минути буфер преди да започне церемонията. Този буфер е свещен - никога не го режете.</p><h2>14:00 - Църковна церемония</h2><p>Средно между 40 и 60 минути. След това - кюфте, ориз, конфети и първите общи кадри.</p><h2>15:00 - Семейни портрети</h2><p>Ако имате списък с 15-20 комбинации, заделете 40 минути. Винаги. Не 20, не 30. Четиридесет.</p><h2>16:00 - Transport до рецепцията</h2><p>Използвайте тези минути в колата за спокойствие и снимки двойката през прозореца.</p><h2>17:00 - Couple session по залез</h2><p>Това е МОМЕНТЪТ. Отделете 45-60 минути само двамата + фотограф + видеооператор. Без гости, без суматоха.</p><h2>18:30 - Влизане в рецепцията</h2><p>Аплодисменти, първи танц, вечеря.</p><blockquote>Правило №1 на сватбения таймлайн: добавете 15 минути буфер към всяко събитие. Правило №2: couple session се случва по залез слънце, не преди и не след. Правило №3: никога не планирайте семейни портрети за време, в което сте гладни.</blockquote><h2>Какво да не правите</h2><p>Не правете церемонията преди 13:00 (твърде ранно за гостите). Не правете couple session преди 16:00 лятото (светлината е жестока). Не оставяте буферите от 5 минути (нищо никога не е 5 минути).</p><p>Ние винаги правим индивидуален таймлайн за всяка сватба, в зависимост от часа на залеза този ден, броя локации и стила на двойката. Това е част от работата ни преди събитието - и е безплатно за всеки наш клиент.</p>',
            ],
            [
                'title' => 'Дрон кадри на сватба - кога си струват и кога не',
                'slug' => 'dron-kadri-svatba',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Дрон заснемането е любима екстра на младоженците, но не всяка сватба има нужда от него. Ето честен анализ кога дронът добавя стойност и кога е излишен разход.',
                'meta_description' => 'Кога дрон заснемането наистина си струва за вашата сватба и кога е излишно. Практичен анализ от Take Two Studio.',
                'body' => '<p>"Ама ще има дрон, нали?" Този въпрос го чуваме на почти всяка първа среща с двойки. И отговорът е винаги един и същ: "Може да има, но зависи." В тази статия обясняваме кога дронът наистина добавя нещо магическо и кога е по-скоро маркетингов gimmick.</p><h2>Кога дронът си струва</h2><h3>Голяма, открита локация</h3><p>Имение на хълм, лозе, плаж, ливада с гости на сватбата. Дронът показва мащаба - нещо, което наземните камери не могат.</p><h3>Уникална архитектура отгоре</h3><p>Църква с кула, замък, кръгъл амфитеатър. Ако сградата има геометрия, която "работи" от въздуха - дронът е задължителен.</p><h3>Голяма група хора</h3><p>Над 100 гости, подредени за общ кадър? От земята не става. От 30 метра - прекрасно.</p><h3>Композиции на групи</h3><p>Напоследък е модерно всички гости да образуват формата на сърце или на инициалите на двойката. Това работи само с дрон.</p><h2>Кога дронът НЕ си струва</h2><h3>Интериорна сватба</h3><p>Ако 80% от деня ви минава в зала или хотел, дронът ще намери 10 минути да поработи. Не си струва сумата.</p><h3>Малки групи и intimate сватби</h3><p>20-30 гости във вила? Нищо за показване отгоре. Интимността се губи с птичи поглед.</p><h3>Лошо време</h3><p>Силен вятър над 10 м/с означава, че дронът няма да полети. Ако прогнозата е мрачна, помислете два пъти.</p><h3>Локации с ограничения</h3><p>Много църкви и манастири забраняват дронове. Варна има регулации около летището. Винаги проверяваме предварително.</p><h2>Кадрите, които си струват</h2><ul><li>Пристигане на булката в локацията - кола, която приближава в perspective</li><li>Общ кадър на всички гости пред залата</li><li>Церемония от високо (само ако е под открито небе)</li><li>Couple shots по залез, с морето отгоре</li><li>First dance от високо - ако танцът е на открито</li></ul><h2>Колко време лети дронът на сватба</h2><p>В реалността - между 15 и 25 минути общо. Всичко останало са подготовки за излитане, смяна на батерия, позициониране. Не очаквайте 1 час "дрон video".</p><blockquote>Ако не сте сигурни, попитайте фотографа си за портфолио от предишни сватби, на които е летял дрон. Ако покаже всички кадри едни и същи безличен "drone view" - вероятно няма да добави нищо за вас.</blockquote><p>При нас в Take Two Studio дрон заснемането е екстра, не част от базовите пакети. Това е съзнателно решение - не всяка сватба го заслужава, и не искаме да взимаме пари за нещо, което няма да видите в албума си.</p>',
            ],
            [
                'title' => 'Какво да облечете за предсватбена фотосесия',
                'slug' => 'predsvatbena-fotosesiya-dreхi',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Предсватбената фотосесия е начин да опознаете фотографа си и да получите красиви снимки преди големия ден. Ето как да изберете дрехи, които ще работят във всяка локация.',
                'meta_description' => 'Какво да облечете за предсватбена фотосесия - практични съвети за цветове, материи и стил от Take Two Studio.',
                'body' => '<p>Предсватбената фотосесия е една от любимите ни услуги. Не заради кадрите (те са бонус), а защото двойките идват непринудени, смеят се, и в края на сесията вече имаме химия - което прави сватбения ден 10 пъти по-лесен. Но има един въпрос, който получаваме постоянно: "Какво да облечем?"</p><h2>Правило №1 - съчетани, не еднакви</h2><p>Не обличайте идентични бели ризи и сини дънки. Това изглежда като семеен портрет от 1995. Съчетаемостта идва от тон, а не от вид дреха. Неутрална цветова палитра, в която двете визии си "говорят".</p><h2>Правило №2 - избягвайте ярки принтове</h2><p>Големи цветя, геометрия, дебели райета, логота - всички те отвличат погледа от лицата ви. Окото на зрителя първо отива на принта, а не на очите ви. Изберете еднотонни дрехи или много фини текстури.</p><h2>Правило №3 - дрехата е за локацията</h2><p>Ако снимаме на плажа - босоноги, леки материи, бели и пясъчно бежови тонове. Ако снимаме в гора - землени цветове: охра, зелено, бордо, ръждиво. Ако сме в стара градска част - класическо елегантни, малко винтидж. Питайте фотографа си за локацията, преди да пазарувате.</p><h2>Правило №4 - комфорт преди стил</h2><p>Обувки, в които ще извървите 3 км. Дреха, в която можете да седнете на трева. Материи, които не се мачкат от една прегръдка. Ако сте неудобни, това ще се вижда на всяка снимка.</p><h3>Цветове, които работят винаги</h3><ul><li>Нежно розово и тъмно зелено</li><li>Крем и каки</li><li>Светло синьо и бяло</li><li>Бордо и сиво</li><li>Черно и пясъчно</li></ul><h3>Цветове, които избягваме</h3><ul><li>Ярко червено (доминира кадъра)</li><li>Неон (не се обработва добре)</li><li>Бял тениска + черни дънки (клише)</li><li>Камуфлажни принтове</li><li>Всичко с логото на някой бранд</li></ul><h2>Два визии, не една</h2><p>Препоръчваме да вземете 2 outfit-а за сесия от 90 минути. Първата визия - по-класическа, елегантна. Втората - спортно-ежедневна, в която може да се превъртате в тревата. Това разнообразява албума и показва личността ви.</p><h2>Аксесоари и детайли</h2><p>Шапка, слънчеви очила, шал, часовник - малките неща добавят характер. Но не прекалявайте. Ако всяка част от облеклото "пише" нещо, общият кадър звучи като шум.</p><blockquote>Последен съвет, от опит: пробвайте дрехата у дома с няколко пози. Протегнете ръце, седнете, прегърнете. Ако нещо ви стяга - не я вземайте на сесията.</blockquote><p>И не на последно място - доверете се на инстинкта си. Дрехи, в които се чувствате красиви, винаги изглеждат по-добре от "правилните" дрехи, в които не се чувствате вие.</p>',
            ],
            [
                'title' => 'Как да направите сватбеното видео личен филм, а не рутинен запис',
                'slug' => 'svatbeno-video-lichen-film',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Разликата между сватбено видео и сватбен филм е в разказването на история. Ето как да помогнете на видеооператора си да създаде нещо, което наистина ще гледате отново.',
                'meta_description' => 'Как да превърнете сватбеното си видео в истински филм - съвети от Take Two Studio за история, музика и емоция.',
                'body' => '<p>Повечето сватбени видеа се гледат веднъж. Един път след медения месец - и после остават забравени в облака. Защо? Защото представляват хронологичен запис "от 10 до 20 часа". Филмът е нещо друго. Филмът разказва история. Ето как го постигаме.</p><h2>Разликата в един ред</h2><p>Видео показва какво се случи. Филм показва как се чувствахте.</p><h2>Любовните писма преди церемонията</h2><p>Една от най-силните техники. Седмица преди сватбата даваме на двете страни листа и тих час. Всеки пише какво чувства за другия точно сега, преди всичко това да започне. Тези думи стават voice-over на финалния филм, наложени над кадри от Getting Ready.</p><p>Резултатът? Не видяхме още двойка, която да не заплаче, когато чуе за пръв път гласа на партньора си, наложен върху собствения им сватбен ден.</p><h2>Интервюта с най-близките</h2><p>Преди церемонията отделяме 5 минути с мама, татко, свидетелите и най-добрата приятелка. По един прост въпрос: "Разкажи ми един момент, който помниш с тях." Тези 30-секундни parts стават разказвачите на филма.</p><h2>Музиката не е добавка, а основа</h2><p>Филмът се "изгражда" около една песен - не върху нея. Ако двойката има своя песен, започваме от нея. Ако няма - избираме заедно преди сватбата. Песента определя настроението, темпото, дължината.</p><h2>Какво да НЕ правите</h2><ul><li>Не искайте "да се включи всичко" - 90-минутни филми никой не гледа</li><li>Не искайте субтитри с имена и дати - това не е документален филм</li><li>Не искайте слоумоушън на всяка стъпка - губи стойност</li><li>Не искайте "Hollywood ефекти" - изглеждат любителски</li></ul><h2>Идеалната дължина</h2><p>3 до 6 минути за кратка версия (highlight). 8 до 15 минути за пълна версия. Всичко над 20 минути - остава в шкафа.</p><h2>Подготовка от ваша страна</h2><p>Кажете ни 3 песни, които обичате. Кажете ни един-два момента, които мечтаете да видите на кадър. Кажете ни каква история искате да разказваме за себе си. Ние сме филмови автори, но сюжетът е ваш.</p><blockquote>Най-добрият комплимент, който получаваме, не е "кадрите са красиви". А "наистина се разпознах в този филм". Това е целта.</blockquote><p>Когато седнете на годишнината си и пуснете филма, искаме първата ви реакция да не е "о, колко беше красиво тогава", а "колко много се обичаме". Това е разликата между видео и филм - и ние работим точно за тази разлика.</p>',
            ],
        ];
